using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Migration.Domain;

public enum MigrationJobState { Created, Discovering, Mapping, DryRun, Importing, Validating, Completed, CompletedWithWarnings, Failed }
public sealed class MigrationJob : ITenantEntity { private MigrationJob() { } public MigrationJob(Guid municipalityId, string sourceBaseUrl, string allowedHost, int maxDepth, int maxPages) { Id = Guid.NewGuid(); MunicipalityId = municipalityId; SourceBaseUrl = sourceBaseUrl.Trim(); AllowedHost = allowedHost.Trim().ToLowerInvariant(); MaxDepth = maxDepth; MaxPages = maxPages; State = MigrationJobState.Created; CreatedAt = UpdatedAt = DateTimeOffset.UtcNow; } public Guid Id { get; private set; } public Guid MunicipalityId { get; private set; } public string SourceBaseUrl { get; private set; } = string.Empty; public string AllowedHost { get; private set; } = string.Empty; public int MaxDepth { get; private set; } public int MaxPages { get; private set; } public MigrationJobState State { get; private set; } public int DiscoveredCount { get; private set; } public int ImportedCount { get; private set; } public int FailedCount { get; private set; } public string? LastError { get; private set; } public DateTimeOffset CreatedAt { get; private set; } public DateTimeOffset UpdatedAt { get; private set; } public DateTimeOffset? CompletedAt { get; private set; } public void Transition(MigrationJobState state, int discovered, int imported, int failed, string? error = null) { State = state; DiscoveredCount = discovered; ImportedCount = imported; FailedCount = failed; LastError = error; UpdatedAt = DateTimeOffset.UtcNow; if (state is MigrationJobState.Completed or MigrationJobState.CompletedWithWarnings or MigrationJobState.Failed) CompletedAt = UpdatedAt; } }
